import{_ as t,o,c as i,a5 as a}from"./chunks/framework.DNkHA0lr.js";const m=JSON.parse('{"title":"The 3-Habit Morning Routine To End Procrastination","description":"","frontmatter":{"title":"The 3-Habit Morning Routine To End Procrastination","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-3-habit-morning-routine-to-end-procrastination.md","filePath":"en/letters/the-3-habit-morning-routine-to-end-procrastination.md"}'),n={name:"en/letters/the-3-habit-morning-routine-to-end-procrastination.md"};function r(l,e,s,p,h,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="the-3-habit-morning-routine-to-end-procrastination" tabindex="-1">The 3-Habit Morning Routine To End Procrastination <a class="header-anchor" href="#the-3-habit-morning-routine-to-end-procrastination" aria-label="Permalink to &quot;The 3-Habit Morning Routine To End Procrastination&quot;">​</a></h1><p>Dan Koe · 2022-04-27 · <a href="https://thedankoe.com/letters/the-3-habit-morning-routine-to-end-procrastination/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-3-habit-morning-routine-to-end-procrastination">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/K47AMrhlw4E?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I’ve tried all of the morning routines.</p><p>I’ve taken them slow, meditated, read for 30 minutes, and everything else like that.</p><p>I always felt like I was behind.</p><p>Stressed and worried about the tasks waiting for me.</p><p>That energy would carry into the rest of my day — they always felt off.</p><p>Over the years of experimentation, I’ve found 3 simple habits was all I needed.</p><p>Having 3 things at the top of mind reduced the friction of getting out of bed.</p><p>Once I had intention and purpose behind my mornings — it made a world of difference.</p><h2 id="the-3-habit-morning-routine" tabindex="-1">The 3 Habit Morning Routine <a class="header-anchor" href="#the-3-habit-morning-routine" aria-label="Permalink to &quot;The 3 Habit Morning Routine&quot;">​</a></h2><p>Mornings are sacred. They set the tone for the rest of the day. Your morning routine should have the purpose of generating energy.</p><p>We want to carry and maintain that energy throughout the day.</p><h3 id="go-on-a-walk" tabindex="-1">Go On A Walk <a class="header-anchor" href="#go-on-a-walk" aria-label="Permalink to &quot;Go On A Walk&quot;">​</a></h3><p>We all know that the body follows the mind, but the mind can also follow the body.</p><p>They play into each other.</p><p>If you want to generate unstoppable momentum into the rest of your day, start by moving your body.</p><p>Better yet, do it outside.</p><blockquote><p>“An early-morning walk is a blessing for the whole day.” – Henry David Thoreau.</p></blockquote><p>Henry was onto something.</p><p>Not only are you getting some of your daily steps in, but you are also exposing your skin to direct sunlight.</p><p>This is critical for healthy circadian biology when you do it on a consistent basis.</p><p>(It will even help you get on a more consistent sleep schedule — maybe you aren’t a night owl after all!)</p><p>You can walk to a coffee shop, around your apartment complex, or wherever else you please.</p><p>Write this down in your planner the night before so it is top of mind in the morning.</p><h3 id="the-10-minute-creative" tabindex="-1">The 10 Minute Creative <a class="header-anchor" href="#the-10-minute-creative" aria-label="Permalink to &quot;The 10 Minute Creative&quot;">​</a></h3><p>Let’s make the snowball of momentum even bigger. Let’s make it impossible for the day to be considered a loss.</p><p>My favorite morning habit is one that I’ve been developing over the years.</p><p>It is a combination of journaling, note-taking, and writing.</p><p>It helps you learn faster, train your creative muscle, and have immense mental clarity.</p><p>(And if you are a creator, it helps you have unlimited ideas for your work.)</p><p>Here’s what you do.</p><p><strong>Step 1) Get Inspired</strong></p><p>Read an article, blink, favorite quote, or page from a book.</p><p>You can also listen to an audiobook during your morning walk!</p><p>Note: these should align with your interests.</p><p>This will give you inspiration for the rest of your day.</p><p><strong>Step 2) Take Note Of Your Excitement</strong></p><p>Dopamine separates signal from noise.</p><p>As you are reading or listening, write down what catches your attention and makes you a bit excited.</p><p>I have a running notes app in my phone that I write all of these down in.</p><p><strong>Step 3) Write A 3-5 Bullet Summary</strong></p><p>What should you include in this summary?</p><ul><li>A description of how YOU understand the topic.</li><li>Personal experiences and stories</li><li>Other ideas that come to mind</li></ul><p>Bonus Step For Creators</p><ul><li>Write out a common problem related to the topic</li><li>Write out the benefits of solving that problem</li><li>Write out steps to overcoming it</li></ul><p>Now you have an outline for a blog, thread, newsletter, or multiple tweets.</p><p>(That’s how I wrote this article.)</p><p><strong>Step 4) One-Sentence Big Idea</strong></p><p>This is where the creativity comes into play.</p><p>From everything you’ve written before, write a one-sentence summary.</p><p>Get creative. Try to write it with the quality of your favorite quote.</p><p>Why are we doing this?</p><ul><li>It gets the creative juices flowing</li><li>It primes your brain for pattern recognition</li><li>It shows you that you CAN be original &amp; profound</li></ul><p>This will only compound as you write more big ideas.</p><p>If you want a guided 7-day challenge for the 10-Minute Creative habit, <a href="https://7daystogenius.com/" target="_blank" rel="noreferrer">here it is.</a></p><h3 id="the-power-hour" tabindex="-1">The Power Hour <a class="header-anchor" href="#the-power-hour" aria-label="Permalink to &quot;The Power Hour&quot;">​</a></h3><p>So far we’ve spent about 20 productive minutes of our morning.</p><p>Our body and mind are ready to keep going. To take on a challenge. To get into flow.</p><p>Next up is what I like to call the Power Hour (no, not the drinking game).</p><blockquote><p>“Happiness is the feeling that power increases – that resistance is being overcome.”</p><p>— Nietzsche</p></blockquote><p>The Power Hour is a 1-hour timeblock that is dedicated to builiding.</p><p>No distractions. One priority. Laser focused.</p><p>Think of it as an automated 1% better everyday.</p><p>What are you building?</p><p>Personal freedom.</p><ul><li>Work on your side business</li><li>Write an article, thread, or book</li><li>Create social media posts</li><li>Learn a marketable skill</li><li>Reach out to potential clients</li></ul><p>You know, the things you said you would start doing but haven’t…</p><p>How do I know what to work on?</p><ul><li>Write out your vision for the future</li><li>Reverse engineer it into a 10-year goal</li><li>Then a 1-year goal</li><li>Then monthly goals</li></ul><p>Now align your Power Hour tasks with that monthly goal.</p><p>Lever-moving fundamental-focused action that results in an automated 1% better everyday. This is why I created <a href="https://shop.thedankoe.com/planer" target="_blank" rel="noreferrer">The Power Planner</a>.</p><p>You will end your Power Hour feeling positive about the future.</p><p>Within 1 hour you have won the day before most people have woken up.</p><p>That feeling is unbeatable.</p><p><strong>To recap:</strong></p><ol><li>Go on a walk for movement and direct sunlight.</li><li>Spend 10-minutes training your creativity muscle.</li><li>Spend 1-hour building a better future for yourself.</li></ol><p>When done consistently, you will look back after 6 months and bask in the progress you made.</p>',79)])])}const c=t(n,[["render",r]]);export{m as __pageData,c as default};
